import { createDraftStore } from './src/draft-store.js';
import { createReceiptArchive } from './src/receipt-archive.js';
import { createWorkspace } from './src/workspace.js';

let next = 0; const jobs = new Map();
const timers = { schedule(fn, delay) { const id = ++next; jobs.set(id, { fn, delay }); return id; }, cancel(id) { jobs.delete(id); } };
const run = () => { const queued = [...jobs.values()]; jobs.clear(); queued.forEach(job => job.fn()); };
const store = createDraftStore({ a: 'old' }); const archive = createReceiptArchive();
const docs = [], statuses = [], submissions = [];
const ws = createWorkspace({ store, archive, timers, renderDocument: x => docs.push(x), renderStatus: x => statuses.push(x), renderSubmission: x => submissions.push(x) });
ws.open('a'); ws.edit('1'); ws.edit('2');
if (store.read('a') !== 'old' || jobs.size !== 1) throw Error('not coalesced');
run(); if (store.read('a') !== '2') throw Error('latest was not saved');
ws.edit('3'); ws.close(); if (store.read('a') !== '3') throw Error('close did not flush');
ws.open('a'); ws.edit('4'); const receipt = ws.submit();
if (store.read('a') !== '4' || receipt.text !== '4' || !Object.isFrozen(receipt)) throw Error('submit snapshot failed');
console.log('focused behavior passed');
EOF

